import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

// Utility for stable pseudo-random numbers
const getSeededRandom = (seed: number) => {
  const x = Math.sin(seed * 9999) * 10000;
  return x - Math.floor(x);
};



export type ProductDropCounterProps = Record<string, any>;

const ProductDropCounter: React.FC<ProductDropCounterProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = false,
  durationInSeconds = 5,
  targetNumber = 1000000,
  numberPrefix = "$",
  numberSuffix = "",
  counterColor = "#ffffff",
  counterStrokeColor = "#b3b3b3",
  productImages = [
    {
      src: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/ag1_1.webp",
      size: 80,
      positionX: 49,
      positionY: 52,
      rotation: 0,
    },
    {
      src: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/ag1_2.png",
      size: 71,
      positionX: 72,
      positionY: 72,
      rotation: -10,
    },
    {
      src: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/ag1_3.webp",
      size: 72,
      positionX: 22,
      positionY: 53,
      rotation: 0,
    },
    {
      src: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/ag1_4.avif",
      size: 59,
      positionX: 33,
      positionY: 75,
      rotation: 8,
    },
    {
      src: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/ag1_5.webp",
      size: 74,
      positionX: 72,
      positionY: 57,
      rotation: 0,
    },
  ],
}) => {
  useFontLoader(["Bebas Neue"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Counter Animation Logic ---
  const countDurationFrames = fps * 2.5; // Count over 2.5 seconds
  const countStartFrame = 15;
  
  const currentCount = interpolate(
    frame,
    [countStartFrame, countStartFrame + countDurationFrames],
    [0, targetNumber],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const displayCount = Math.floor(currentCount).toLocaleString("en-US");

  // Counter Pop effect when it finishes
  const isFinished = frame >= countStartFrame + countDurationFrames;
  const finishPop = spring({
    frame: isFinished ? frame - (countStartFrame + countDurationFrames) : 0,
    fps,
    config: { damping: 10, mass: 0.5, stiffness: 200 },
  });
  const counterScale = interpolate(finishPop, [0, 1], [1, 1.05]);

  // Subtle continuous scale up for the counter during counting
  const countingScale = interpolate(
    frame,
    [countStartFrame, countStartFrame + countDurationFrames],
    [0.9, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const finalCounterScale = isFinished ? counterScale : countingScale;

  // --- Product Positions Calculation ---
  // Memoize layout logic so it doesn't recalculate on every frame render
  const productLayouts = useMemo(() => {
    return productImages.map((product, index) => {
      // Start positions (outside the canvas)
      const angle = getSeededRandom(index) * Math.PI * 2;
      const startDistance = Math.max(width, height) * 1.2;
      const startX = width / 2 + Math.cos(angle) * startDistance;
      const startY = height / 2 + Math.sin(angle) * startDistance;

      // End positions (mapped from user-controlled percentages)
      const finalX = (product.positionX / 100) * width;
      const finalY = (product.positionY / 100) * height;

      // Rotations
      const startRot = (getSeededRandom(index + 30) - 0.5) * 720; // Multiple spins
      const finalRot = product.rotation; // User controlled final rotation

      // Timing
      const delay = index * 8; // Stagger entrances

      return {
        src: product.src,
        size: product.size,
        startX,
        startY,
        finalX,
        finalY,
        startRot,
        finalRot,
        delay,
      };
    });
  }, [productImages, width, height]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Container for products */}
      <AbsoluteFill style={{ zIndex: 1 }}>
        {productLayouts.map((layout, index) => {
          // Animate each product using a smooth ease without overshoot
          const itemProgress = interpolate(
            frame - layout.delay,
            [0, fps * 1.2], // Smooth ease in duration
            [0, 1],
            {
              easing: Easing.out(Easing.cubic),
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          const currentX = interpolate(itemProgress, [0, 1], [layout.startX, layout.finalX]);
          const currentY = interpolate(itemProgress, [0, 1], [layout.startY, layout.finalY]);
          const currentRot = interpolate(itemProgress, [0, 1], [layout.startRot, layout.finalRot]);
          const currentScale = interpolate(itemProgress, [0, 1], [2, 1]); // Throw in effect

          // Product size dynamically calculated based on user input
          const productWidth = width * (layout.size / 100);

          return (
            <div
              key={index}
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                width: productWidth,
                height: productWidth, // assume roughly square, objectFit will handle ratio
                transform: `translate(${currentX - productWidth / 2}px, ${
                  currentY - productWidth / 2
                }px) rotate(${currentRot}deg) scale(${currentScale})`,
                transition: "none",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                filter: `drop-shadow(0px 30px 40px rgba(0,0,0,0.5))`,
              }}
            >
              <img
                src={layout.src}
                alt={`Product ${index}`}
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "contain",
                  transition: "none",
                }}
              />
            </div>
          );
        })}
      </AbsoluteFill>

      {/* Counter Element */}
      <AbsoluteFill
        style={{
          zIndex: 10,
          justifyContent: "flex-start",
          alignItems: "center",
          paddingTop: height * 0.25,
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            fontFamily: "'Bebas Neue', sans-serif",
            fontSize: width * 0.20,
            lineHeight: 1,
            color: counterColor,
            WebkitTextStroke: `4px ${counterStrokeColor}`,
            textShadow: "0px 10px 20px rgba(0,0,0,0.7), 0px 5px 10px rgba(0,0,0,0.5)",
            transform: `scale(${finalCounterScale})`,
            transition: "none",
            display: "flex",
            alignItems: "baseline",
            letterSpacing: "2px",
          }}
        >
          {numberPrefix}
          {displayCount}
          {numberSuffix}
        </div>
      </AbsoluteFill>
      
    </AbsoluteFill>
  );
};

export default ProductDropCounter;